 @import "tailwindcss";

 /*
  * The Management Console switches theme through `data-theme` on <html>
  * rather than the OS preference, so Poster's Light/Dark toggle is explicit.
  */
 @custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

 @theme inline {
   --font-sans: var(--font-inter);
   --font-mono: var(--font-jetbrains-mono);
 }

 :root {
   --console-canvas: #ffffff;
   --console-panel: #f7f8fa;
   --console-border: #e5e8ec;
   color-scheme: light;
 }

 [data-theme="dark"] {
   --console-canvas: #24272c;
   --console-panel: #1d2024;
   --console-border: #33373e;
   color-scheme: dark;
 }

 html,
 body {
   height: 100%;
 }

 body {
   font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
   background: var(--console-canvas);
   color: #1f2430;
 }

 [data-theme="dark"] body {
   color: #e8eaed;
 }

 /* Poster uses the mono face for money, receipt numbers and stock quantities. */
 .tabular-money {
   font-family: var(--font-mono), ui-monospace, SFMono-Regular, monospace;
   font-variant-numeric: tabular-nums;
 }

 /* Clean Poster-style scrollbars */
 ::-webkit-scrollbar {
   width: 6px;
   height: 6px;
 }
 ::-webkit-scrollbar-track {
   background: transparent;
 }
 ::-webkit-scrollbar-thumb {
   background: rgba(148, 163, 184, 0.45);
   border-radius: 9999px;
 }
 ::-webkit-scrollbar-thumb:hover {
   background: rgba(100, 116, 139, 0.7);
 }

 /* Serrated thermal receipt paper */
 .thermal-receipt,
 .receipt-paper {
   background: #ffffff;
   color: #1e293b;
   position: relative;
   box-shadow:
     0 20px 25px -5px rgba(15, 23, 42, 0.18),
     0 8px 10px -6px rgba(15, 23, 42, 0.12);
 }
 .thermal-receipt::before,
 .thermal-receipt::after,
 .receipt-paper::before,
 .receipt-paper::after {
   content: "";
   position: absolute;
   left: 0;
   right: 0;
   height: 8px;
   background-size: 16px 8px;
 }
 .thermal-receipt::before,
 .receipt-paper::before {
   top: -8px;
   background-image: radial-gradient(circle at 8px 0, transparent 6px, #ffffff 6.5px);
 }
 .thermal-receipt::after,
 .receipt-paper::after {
   bottom: -8px;
   background-image: radial-gradient(circle at 8px 8px, transparent 6px, #ffffff 6.5px);
 }

 @media print {
   body * {
     visibility: hidden;
   }
   #printable-receipt-area,
   #printable-receipt-area * {
     visibility: visible;
   }
   #printable-receipt-area {
     position: fixed;
     left: 50%;
     top: 0;
     transform: translateX(-50%);
     width: 320px;
     box-shadow: none !important;
   }
 }

