   actions = {},
 }: {
   title: string;
   count?: number | string;
   actions?: PageActions;
 }) {
   const { actions: storeActions } = usePosStore();

   return (
     <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#E5E8EC] pb-3.5 dark:border-[#33373E]">
